function isPalindrome(s) {
  const t = s.toLowerCase();
  let i = 0;
  let j = t.length - 1;
  while (i < j) {
    if (t[i] !== t[j]) return false;
    i++;
    j--;
  }
  return true;
}

function isPalindrome(s) {
  const str = s.toLowerCase();
  let left = 0;
  let right = str.length - 1;
  while (left < right) {
    if (str[left] !== str[right]) return false;
    left++;
    right--;
  }
  return true;
}
